async (page) => {
  await page.addInitScript(() => {
    if (window.top !== window) return;
    window.__tl = []; const t0 = performance.now(); let last = '';
    setInterval(() => {
      const rows = [...document.querySelectorAll('tr')].map(r => r.innerText.replace(/\s+/g, ' '));
      const kind = rows.find(r => /^kind/.test(r)) || null;
      const extra = rows.find(r => /^extra/.test(r)) || null;
      const s = rows.length + '|' + kind + '|' + extra;
      if (s !== last) { last = s; window.__tl.push({ ms: Math.round(performance.now() - t0), rows: rows.length, kind, extra }); }
    }, 50);
  });
  const t = Date.now();
  await page.goto('http://127.0.0.1:6217/?path=/story/demo-button--primary');
  await page.waitForTimeout(15000);
  const tl = await page.evaluate(() => window.__tl);
  require('fs').writeFileSync('/Users/gabe/Projects/caliper/.playwright-mcp/timeline.json', JSON.stringify(tl, null, 1));
  await page.screenshot({ path: '/Users/gabe/Projects/caliper/.playwright-mcp/after-chakra.png' });
  return tl;
}

